from __future__ import annotations

import base64
import io
import tarfile
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
PAYLOAD = """"""

archive = base64.b64decode(PAYLOAD)
with tarfile.open(fileobj=io.BytesIO(archive), mode="r:gz") as tar:
    tar.extractall(ROOT)

for relative in (
    ".github/scripts/apply_code_split_followup.py",
    ".github/workflows/apply-code-split-followup.yml",
):
    path = ROOT / relative
    if path.exists():
        path.unlink()
try:
    (ROOT / ".github/scripts").rmdir()
except OSError:
    pass
